/**
 * AccountsRoute tests (Queue Accounts, Task 8) — the /queue/accounts surface
 * wiring useAccountGroups + useAccounts to AccountsEmptyState /
 * CreateGroupForm / GroupList / AccountList / AddAccountForm.
 *
 * Structured like ask-mfe's SurveysCreateRoute.test.tsx: real hooks + real
 * api layer, network mocked via the shared MSW `server` from
 * tests/setup.ts (registered per-test — there's no default account/group
 * handler in tests/msw/handlers.ts). This exercises the actual
 * create-group -> see-it-listed -> select -> add-account flow end to end,
 * not a hook-mocked shallow render. Asserted via accessible queries only.
 */

import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { http, HttpResponse } from "msw";
import { afterEach, describe, expect, it } from "vitest";
import { server } from "../../../tests/setup";
import AccountsRoute from "../AccountsRoute";
import type { AccountGroupDTO, SocialAccountDTO } from "../../api/accounts";

function groupsHandler(groups: readonly AccountGroupDTO[]) {
  return http.get("/api/v1/queue/account-groups", () =>
    HttpResponse.json({ data: { groups, next_page_token: "" } }),
  );
}

function accountsHandler(accounts: readonly SocialAccountDTO[]) {
  return http.get("/api/v1/queue/accounts", ({ request }) => {
    const url = new URL(request.url);
    const groupId = url.searchParams.get("group_id");
    const filtered = groupId
      ? accounts.filter((a) => a.group_id === groupId)
      : accounts;
    return HttpResponse.json({ data: { accounts: filtered, next_page_token: "" } });
  });
}

const GROUP_A: AccountGroupDTO = {
  id: "g-1",
  org_id: "org-1",
  name: "Ion launch accounts",
  group_type: "ion",
  created_at: "2026-07-01T00:00:00Z",
};

const GROUP_B: AccountGroupDTO = {
  id: "g-2",
  org_id: "org-1",
  name: "Range training accounts",
  group_type: "range",
  created_at: "2026-07-02T00:00:00Z",
};

afterEach(() => {
  server.resetHandlers();
});

describe("AccountsRoute", () => {
  it("shows a loading status while account groups are loading", () => {
    server.use(
      http.get("/api/v1/queue/account-groups", () => new Promise(() => undefined)),
    );

    render(<AccountsRoute />);
    expect(screen.getByRole("status")).toBeInTheDocument();
  });

  it("shows a retry alert on failure, and recovers on Try again", async () => {
    const user = userEvent.setup();
    let attempt = 0;
    server.use(
      http.get("/api/v1/queue/account-groups", () => {
        attempt += 1;
        if (attempt === 1) {
          return HttpResponse.json(
            { error: { code: "internal", message: "boom" } },
            { status: 500 },
          );
        }
        return HttpResponse.json({ data: { groups: [], next_page_token: "" } });
      }),
    );

    render(<AccountsRoute />);

    expect(
      await screen.findByText("Couldn't load account groups"),
    ).toBeInTheDocument();

    await user.click(screen.getByRole("button", { name: "Try again" }));

    expect(
      await screen.findByRole("heading", { name: "Create your first account group" }),
    ).toBeInTheDocument();
  });

  it("runs the full create-group -> see-it-listed -> select -> add-account flow", async () => {
    const user = userEvent.setup();
    let groups: AccountGroupDTO[] = [];
    let accounts: SocialAccountDTO[] = [];

    server.use(
      http.get("/api/v1/queue/account-groups", () =>
        HttpResponse.json({ data: { groups, next_page_token: "" } }),
      ),
      http.post("/api/v1/queue/account-groups", async ({ request }) => {
        const body = (await request.json()) as {
          name: string;
          group_type: string;
        };
        const created: AccountGroupDTO = {
          id: "g-new",
          org_id: "org-1",
          name: body.name,
          group_type: body.group_type as AccountGroupDTO["group_type"],
          created_at: "2026-07-24T00:00:00Z",
        };
        groups = [...groups, created];
        return HttpResponse.json({ data: created }, { status: 201 });
      }),
      http.get("/api/v1/queue/accounts", ({ request }) => {
        const url = new URL(request.url);
        const groupId = url.searchParams.get("group_id");
        const filtered = groupId
          ? accounts.filter((a) => a.group_id === groupId)
          : accounts;
        return HttpResponse.json({
          data: { accounts: filtered, next_page_token: "" },
        });
      }),
      http.post("/api/v1/queue/accounts", async ({ request }) => {
        const body = (await request.json()) as {
          group_id?: string;
          platform: string;
          handle: string;
        };
        const created: SocialAccountDTO = {
          id: "a-new",
          org_id: "org-1",
          group_id: body.group_id,
          platform: body.platform as SocialAccountDTO["platform"],
          handle: body.handle,
          status: "connected",
        };
        accounts = [...accounts, created];
        return HttpResponse.json({ data: created }, { status: 201 });
      }),
    );

    render(<AccountsRoute />);

    // 1. Empty state first (no groups yet).
    await user.click(
      await screen.findByRole("button", { name: "Create group" }),
    );

    // 2. Fill + submit the create-group form (default type is ION).
    await user.type(
      await screen.findByLabelText("Group name"),
      "Ion launch accounts",
    );
    await user.click(screen.getByRole("button", { name: "Create group" }));

    // 3. See-it-listed: the new group is auto-selected in the GroupList.
    const groupButton = await screen.findByRole("button", {
      name: /Ion launch accounts/,
    });
    await waitFor(() =>
      expect(groupButton).toHaveAttribute("aria-pressed", "true"),
    );

    // 4. The (empty) accounts panel for the new group.
    expect(
      await screen.findByRole("heading", {
        name: "No accounts in this group yet",
      }),
    ).toBeInTheDocument();

    // 5. Add an account via AddAccountForm.
    await user.type(screen.getByLabelText("Handle"), "@ioncomms");
    await user.click(screen.getByRole("button", { name: "Add account" }));

    // 6. It shows up in the AccountList after the refetch.
    expect(await screen.findByText("@ioncomms")).toBeInTheDocument();
  });

  it("switches the accounts panel when a different existing group is selected", async () => {
    const user = userEvent.setup();
    server.use(
      groupsHandler([GROUP_A, GROUP_B]),
      accountsHandler([
        {
          id: "a-1",
          org_id: "org-1",
          group_id: "g-1",
          platform: "twitter",
          handle: "@group-a-account",
          status: "connected",
        },
        {
          id: "a-2",
          org_id: "org-1",
          group_id: "g-2",
          platform: "linkedin",
          handle: "group-b-account",
          status: "connected",
        },
      ]),
    );

    render(<AccountsRoute />);

    await user.click(
      await screen.findByRole("button", { name: /Ion launch accounts/ }),
    );
    expect(await screen.findByText("@group-a-account")).toBeInTheDocument();

    await user.click(
      screen.getByRole("button", { name: /Range training accounts/ }),
    );
    expect(await screen.findByText("group-b-account")).toBeInTheDocument();
    expect(screen.queryByText("@group-a-account")).not.toBeInTheDocument();
  });

  it("shows a retry alert for the selected group's accounts when that fetch fails", async () => {
    const user = userEvent.setup();
    let attempt = 0;
    server.use(
      groupsHandler([GROUP_A]),
      http.get("/api/v1/queue/accounts", ({ request }) => {
        const url = new URL(request.url);
        // useAccounts is gated (enabled: selectedGroupId !== null), so no
        // unscoped request should ever land here — fail loudly if one does.
        expect(url.searchParams.get("group_id")).not.toBeNull();
        attempt += 1;
        if (attempt === 1) {
          return HttpResponse.json(
            { error: { code: "internal", message: "boom" } },
            { status: 500 },
          );
        }
        return HttpResponse.json({ data: { accounts: [], next_page_token: "" } });
      }),
    );

    render(<AccountsRoute />);

    await user.click(
      await screen.findByRole("button", { name: /Ion launch accounts/ }),
    );

    expect(await screen.findByText("Couldn't load accounts")).toBeInTheDocument();

    await user.click(screen.getByRole("button", { name: "Try again" }));

    expect(
      await screen.findByRole("heading", {
        name: "No accounts in this group yet",
      }),
    ).toBeInTheDocument();
  });

  it("does not fire an unscoped accounts fetch before any group is selected", async () => {
    let accountsRequests = 0;
    server.use(
      groupsHandler([GROUP_A]),
      http.get("/api/v1/queue/accounts", () => {
        accountsRequests += 1;
        return HttpResponse.json({ data: { accounts: [], next_page_token: "" } });
      }),
    );

    render(<AccountsRoute />);

    await screen.findByRole("button", { name: /Ion launch accounts/ });
    expect(
      screen.getByText("Select a group to view its accounts"),
    ).toBeInTheDocument();

    expect(accountsRequests).toBe(0);
  });

  it("never renders another group's accounts when a group is first selected (no wrong-data flash)", async () => {
    const user = userEvent.setup();
    server.use(
      groupsHandler([GROUP_A, GROUP_B]),
      accountsHandler([
        {
          id: "a-1",
          org_id: "org-1",
          group_id: "g-1",
          platform: "twitter",
          handle: "@group-a-account",
          status: "connected",
        },
        {
          id: "a-2",
          org_id: "org-1",
          group_id: "g-2",
          platform: "linkedin",
          handle: "group-b-account",
          status: "connected",
        },
      ]),
    );

    render(<AccountsRoute />);

    await user.click(
      await screen.findByRole("button", { name: /Range training accounts/ }),
    );

    // The very first accounts fetch is already scoped to g-2 — g-1's account
    // must never appear, not even transiently.
    expect(await screen.findByText("group-b-account")).toBeInTheDocument();
    expect(screen.queryByText("@group-a-account")).not.toBeInTheDocument();
  });

  it("cancels out of the create-group form back to the empty state", async () => {
    const user = userEvent.setup();
    server.use(groupsHandler([]), accountsHandler([]));

    render(<AccountsRoute />);

    await user.click(
      await screen.findByRole("button", { name: "Create group" }),
    );
    await screen.findByLabelText("Group name");

    await user.click(screen.getByRole("button", { name: "Cancel" }));

    expect(
      await screen.findByRole("heading", {
        name: "Create your first account group",
      }),
    ).toBeInTheDocument();
  });

  it("opens the create-group form via GroupList's New group action", async () => {
    const user = userEvent.setup();
    server.use(groupsHandler([GROUP_A]), accountsHandler([]));

    render(<AccountsRoute />);

    await user.click(await screen.findByRole("button", { name: "New group" }));

    expect(
      await screen.findByRole("heading", { name: "New account group" }),
    ).toBeInTheDocument();
  });
});

// ---------------------------------------------------------------------------
// #1238 — rename, delete, and the selection cleanup a delete forces.
// ---------------------------------------------------------------------------

describe("AccountsRoute — group rename (#1238)", () => {
  it("renames a group and repaints the list from the refetch", async () => {
    const user = userEvent.setup();
    let renamed = false;
    server.use(
      http.get("/api/v1/queue/account-groups", () =>
        HttpResponse.json({
          data: {
            groups: [renamed ? { ...GROUP_A, name: "Renamed Cell" } : GROUP_A],
            next_page_token: "",
          },
        }),
      ),
      http.put("/api/v1/queue/account-groups/g-1", async ({ request }) => {
        const body = (await request.json()) as { name: string };
        renamed = true;
        return HttpResponse.json({ data: { ...GROUP_A, name: body.name } });
      }),
      accountsHandler([]),
    );
    render(<AccountsRoute />);

    await user.click(
      (await screen.findAllByRole("button", { name: "Rename group" }))[0],
    );
    const field = screen.getByLabelText("Rename account group");
    await user.clear(field);
    await user.type(field, "Renamed Cell");
    await user.click(screen.getByRole("button", { name: "Save" }));

    expect(await screen.findByText("Renamed Cell")).toBeInTheDocument();
  });

  it("surfaces a duplicate-name 409 inline and leaves the old name listed", async () => {
    const user = userEvent.setup();
    server.use(
      groupsHandler([GROUP_A]),
      http.put("/api/v1/queue/account-groups/g-1", () =>
        HttpResponse.json(
          { error: { message: "group name taken" } },
          { status: 409 },
        ),
      ),
      accountsHandler([]),
    );
    render(<AccountsRoute />);

    await user.click(
      (await screen.findAllByRole("button", { name: "Rename group" }))[0],
    );
    await user.click(screen.getByRole("button", { name: "Save" }));

    expect(await screen.findByRole("alert")).toHaveTextContent(
      "An account group with that name already exists",
    );
  });
});

describe("AccountsRoute — group delete (#1238)", () => {
  it("confirms with the group's real account count before deleting", async () => {
    const user = userEvent.setup();
    server.use(
      groupsHandler([{ ...GROUP_A, account_count: 2 }]),
      accountsHandler([]),
    );
    render(<AccountsRoute />);

    await user.click(
      (await screen.findAllByRole("button", { name: "Delete group" }))[0],
    );

    expect(
      await screen.findByText(
        "Deleting “Ion launch accounts” also removes its 2 connected accounts. This can't be undone.",
      ),
    ).toBeInTheDocument();
  });

  it("removes the group from the list once the delete succeeds", async () => {
    const user = userEvent.setup();
    let deleted = false;
    server.use(
      http.get("/api/v1/queue/account-groups", () =>
        HttpResponse.json({
          data: { groups: deleted ? [GROUP_B] : [GROUP_A, GROUP_B], next_page_token: "" },
        }),
      ),
      http.delete("/api/v1/queue/account-groups/g-1", () => {
        deleted = true;
        return new HttpResponse(null, { status: 204 });
      }),
      accountsHandler([]),
    );
    render(<AccountsRoute />);

    await screen.findByText("Ion launch accounts");
    await user.click(screen.getAllByRole("button", { name: "Delete group" })[0]);
    await user.click(
      await screen.findByRole("button", { name: "Delete group" }),
    );

    await waitFor(() => {
      expect(screen.queryByText("Ion launch accounts")).not.toBeInTheDocument();
    });
    expect(screen.getByText("Range training accounts")).toBeInTheDocument();
  });

  it("clears the selection when the DELETED group was the selected one", async () => {
    const user = userEvent.setup();
    let deleted = false;
    server.use(
      http.get("/api/v1/queue/account-groups", () =>
        HttpResponse.json({
          data: { groups: deleted ? [GROUP_B] : [GROUP_A, GROUP_B], next_page_token: "" },
        }),
      ),
      http.delete("/api/v1/queue/account-groups/g-1", () => {
        deleted = true;
        return new HttpResponse(null, { status: 204 });
      }),
      accountsHandler([]),
    );
    render(<AccountsRoute />);

    // Select the group first, so the accounts pane is bound to it.
    await user.click(await screen.findByText("Ion launch accounts"));
    await screen.findByRole("heading", { name: "Accounts" });

    await user.click(screen.getAllByRole("button", { name: "Delete group" })[0]);
    await user.click(
      await screen.findByRole("button", { name: "Delete group" }),
    );

    // Back to the "pick a group" prompt rather than an accounts pane still
    // querying the id that no longer exists.
    expect(
      await screen.findByText("Select a group to view its accounts"),
    ).toBeInTheDocument();
  });

  it("keeps the group listed when the delete fails", async () => {
    const user = userEvent.setup();
    server.use(
      groupsHandler([GROUP_A]),
      http.delete("/api/v1/queue/account-groups/g-1", () =>
        HttpResponse.json({ error: { message: "boom" } }, { status: 500 }),
      ),
      accountsHandler([]),
    );
    render(<AccountsRoute />);

    await user.click(
      (await screen.findAllByRole("button", { name: "Delete group" }))[0],
    );
    await user.click(
      await screen.findByRole("button", { name: "Delete group" }),
    );

    expect(await screen.findByRole("alert")).toHaveTextContent(
      "Couldn't delete the group. Try again.",
    );
    expect(screen.getByText("Ion launch accounts")).toBeInTheDocument();
  });
});

// ---------------------------------------------------------------------------
// Review #3042: the sidebar count must not go stale after adding an account.
//
// The count badge reads from the GROUP-list snapshot, but AddAccountForm's
// onAdded only refetched the ACCOUNTS list, so the badge kept rendering the
// stale account_count until some unrelated action happened to refetch groups.
// That also fed the delete confirmation, which then claimed "no accounts"
// while cascading real ones — the reason this sequence gets its own test.
// ---------------------------------------------------------------------------

describe("AccountsRoute — count freshness after adding an account (#3042)", () => {
  it("refetches the group list so the sidebar count reflects the new account", async () => {
    const user = userEvent.setup();
    let accountCount = 0;
    const added: SocialAccountDTO[] = [];

    server.use(
      http.get("/api/v1/queue/account-groups", () =>
        HttpResponse.json({
          data: {
            groups: [{ ...GROUP_A, account_count: accountCount }],
            next_page_token: "",
          },
        }),
      ),
      http.get("/api/v1/queue/accounts", () =>
        HttpResponse.json({ data: { accounts: added, next_page_token: "" } }),
      ),
      http.post("/api/v1/queue/accounts", async () => {
        // The server-side count subquery is correct; this mirrors it.
        accountCount += 1;
        const account: SocialAccountDTO = {
          id: `a-${accountCount}`,
          org_id: "org-1",
          group_id: GROUP_A.id,
          platform: "twitter",
          handle: `@h${accountCount}`,
          status: "connected",
        };
        added.push(account);
        return HttpResponse.json({ data: account });
      }),
    );

    render(<AccountsRoute />);

    await user.click(await screen.findByText("Ion launch accounts"));
    expect(await screen.findByText("Accounts: 0")).toBeInTheDocument();

    await user.type(screen.getByLabelText(/handle/i), "@first");
    await user.click(screen.getByRole("button", { name: /^add account$/i }));

    // Without the group-list refetch this stays "Accounts: 0" indefinitely.
    expect(await screen.findByText("Accounts: 1")).toBeInTheDocument();
  });

  it("carries the fresh count into the delete confirmation", async () => {
    const user = userEvent.setup();
    let accountCount = 0;
    const added: SocialAccountDTO[] = [];

    server.use(
      http.get("/api/v1/queue/account-groups", () =>
        HttpResponse.json({
          data: {
            groups: [{ ...GROUP_A, account_count: accountCount }],
            next_page_token: "",
          },
        }),
      ),
      http.get("/api/v1/queue/accounts", () =>
        HttpResponse.json({ data: { accounts: added, next_page_token: "" } }),
      ),
      http.post("/api/v1/queue/accounts", async () => {
        accountCount += 1;
        const account: SocialAccountDTO = {
          id: `a-${accountCount}`,
          org_id: "org-1",
          group_id: GROUP_A.id,
          platform: "twitter",
          handle: `@h${accountCount}`,
          status: "connected",
        };
        added.push(account);
        return HttpResponse.json({ data: account });
      }),
    );

    render(<AccountsRoute />);

    await user.click(await screen.findByText("Ion launch accounts"));
    await user.type(screen.getByLabelText(/handle/i), "@first");
    await user.click(screen.getByRole("button", { name: /^add account$/i }));
    await screen.findByText("Accounts: 1");

    await user.click(screen.getAllByRole("button", { name: "Delete group" })[0]);

    // The destructive confirmation must NOT claim the group is empty.
    expect(
      await screen.findByText(
        "Deleting “Ion launch accounts” also removes its 1 connected account. This can't be undone.",
      ),
    ).toBeInTheDocument();
    expect(
      screen.queryByText(
        "This group has no accounts. Deleting it can't be undone.",
      ),
    ).not.toBeInTheDocument();
  });
});


