        HttpResponse.json({
          data: {
            groups: [{ ...GROUP_A, account_count: accountCount }],
            next_page_token: "",
          },
        }),
      ),
      http.get("/api/v1/queue/accounts", () =>
        HttpResponse.json({ data: { accounts: added, next_page_token: "" } }),
      ),
