/**
 * QueueLandingRoute tests (Queue Posts, Task 9; schedule wired in Task 7) —
 * the /queue Posts surface: wires usePosts (ALL posts, unscoped — no status
 * filter) + useAccounts (chip resolution) to PostsEmptyState / PostsList /
 * ComposePostModal. Structured like AccountsRoute.test.tsx: real hooks +
 * real api layer, network mocked via the shared MSW `server` from
 * tests/setup.ts — this exercises the actual create -> see-it-listed, edit
 * -> updated, delete -> removed, and schedule -> STILL-listed-with-its-new-
 * status flows end to end, not a hook-mocked shallow render. Asserted via
 * accessible queries only.
 *
 * Regression coverage (bug: a scheduled post vanished from /queue): the
 * mock GET handlers below deliberately mirror the real queue-bff's
 * server-side `?status=` filtering (see api/posts.ts's listPosts) rather
 * than ignoring the query string, so a test that renders a scheduled post
 * actually exercises whether the route still asks for `status=draft` —
 * exactly what regressed. A handler that ignored the query string
 * entirely would pass whether or not the route was still scoped to drafts.
 */

import { fireEvent, render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { http, HttpResponse } from "msw";
import { afterEach, describe, expect, it } from "vitest";
import { server } from "../../../tests/setup";
import QueueLandingRoute from "../QueueLandingRoute";
import type { PostDTO } from "../../api/posts";

function noAccountGroupsHandlers() {
  return [
    http.get("/api/v1/queue/account-groups", () =>
      HttpResponse.json({ data: { groups: [], next_page_token: "" } }),
    ),
    http.get("/api/v1/queue/accounts", () =>
      HttpResponse.json({ data: { accounts: [], next_page_token: "" } }),
    ),
  ];
}

/** Mirrors queue-bff's real server-side `?status=` filtering (see
 * api/posts.ts's listPosts doc) — a request with no `status` param gets
 * every post back; a request WITH one only gets posts matching it. Records
 * every request URL seen so a test can assert on whether `status` was
 * forwarded at all. */
function listPostsHandler(
  getPosts: () => readonly PostDTO[],
  requestUrls: string[],
) {
  return http.get("/api/v1/queue/posts", ({ request }) => {
    requestUrls.push(request.url);
    const status = new URL(request.url).searchParams.get("status");
    const posts = getPosts();
    const filtered = status ? posts.filter((p) => p.status === status) : posts;
    return HttpResponse.json({ data: { posts: filtered, next_page_token: "" } });
  });
}

afterEach(() => {
  server.resetHandlers();
});

describe("QueueLandingRoute", () => {
  it("shows a loading status while posts are loading", () => {
    server.use(
      http.get("/api/v1/queue/posts", () => new Promise(() => undefined)),
      ...noAccountGroupsHandlers(),
