/**
 * TableRoute tests (Task 7) — the `/queue/table` surface: wires usePosts
 * (status-filtered) + useAccounts (chip resolution) to a sortable table +
 * status filter, with loading/empty/error states. Structured like
 * QueueLandingRoute.test.tsx: real hooks + real api layer, network mocked
 * via the shared MSW `server` from tests/setup.ts. The
 * Schedule/Reschedule/Revert action cluster's own full flow is exercised in
 * PostScheduleActions.test.tsx / SchedulePostControl.test.tsx — these tests
 * only confirm the table renders posts, filters, and sorts correctly.
 * Asserted via accessible queries only.
 */

import { fireEvent, render, screen, waitFor, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { http, HttpResponse } from "msw";
import { afterEach, describe, expect, it } from "vitest";
import { server } from "../../../tests/setup";
import TableRoute from "../TableRoute";
import type { PostDTO } from "../../api/posts";
import type { SocialAccountDTO } from "../../api/accounts";

const ACCOUNT_A1: SocialAccountDTO = {
  id: "a-1",
  org_id: "org-1",
  group_id: "g-1",
  platform: "twitter",
  handle: "@ioncomms",
  status: "connected",
};

function postsHandler(posts: readonly PostDTO[]) {
  return http.get("/api/v1/queue/posts", ({ request }) => {
    const url = new URL(request.url);
    const status = url.searchParams.get("status");
    const filtered = status ? posts.filter((p) => p.status === status) : posts;
    return HttpResponse.json({ data: { posts: filtered, next_page_token: "" } });
  });
}

function accountsHandler(accounts: readonly SocialAccountDTO[] = []) {
  return http.get("/api/v1/queue/accounts", () =>
    HttpResponse.json({ data: { accounts, next_page_token: "" } }),
  );
}

const DRAFT_POST: PostDTO = {
  id: "p-1",
  org_id: "org-1",
  content: "alpha post",
  status: "draft",
  account_ids: [],
  created_at: "2026-08-01T00:00:00Z",
  updated_at: "2026-08-01T00:00:00Z",
};

const SCHEDULED_POST: PostDTO = {
  id: "p-2",
  org_id: "org-1",
  content: "beta post",
  status: "scheduled",
  account_ids: ["a-1"],
  scheduled_at: "2099-01-01T00:00:00Z",
  created_at: "2026-08-01T00:00:00Z",
  updated_at: "2026-08-01T00:00:00Z",
};

afterEach(() => {
  server.resetHandlers();
});

describe("TableRoute", () => {
  it("shows a loading status while posts are loading", () => {
    server.use(
      http.get("/api/v1/queue/posts", () => new Promise(() => undefined)),
      accountsHandler(),
    );

    render(<TableRoute />);
    expect(screen.getByRole("status")).toBeInTheDocument();
  });

  it("shows a retry alert on failure, and recovers on Try again", async () => {
    const user = userEvent.setup();
    let attempt = 0;
    server.use(
      http.get("/api/v1/queue/posts", () => {
        attempt += 1;
        if (attempt === 1) {
          return HttpResponse.json(
            { error: { code: "internal", message: "boom" } },
            { status: 500 },
          );
        }
        return HttpResponse.json({ data: { posts: [], next_page_token: "" } });
      }),
      accountsHandler(),
    );

    render(<TableRoute />);

    expect(await screen.findByText("Couldn't load posts")).toBeInTheDocument();
    await user.click(screen.getByRole("button", { name: "Try again" }));

    expect(
      await screen.findByRole("heading", { name: "No posts match this filter" }),
    ).toBeInTheDocument();
  });

  it("shows the empty state when there are no posts", async () => {
    server.use(postsHandler([]), accountsHandler());

    render(<TableRoute />);

    expect(
      await screen.findByRole("heading", { name: "No posts match this filter" }),
    ).toBeInTheDocument();
  });

  it("renders column headers and a row per post, with resolved account chips", async () => {
    server.use(postsHandler([DRAFT_POST, SCHEDULED_POST]), accountsHandler([ACCOUNT_A1]));

    render(<TableRoute />);

    expect(await screen.findByText("alpha post")).toBeInTheDocument();
    expect(screen.getByText("beta post")).toBeInTheDocument();

    expect(screen.getByRole("columnheader", { name: "Accounts" })).toBeInTheDocument();
    expect(screen.getByRole("button", { name: "Content" })).toBeInTheDocument();
    expect(screen.getByRole("button", { name: "Status" })).toBeInTheDocument();
    expect(screen.getByRole("button", { name: "Scheduled for" })).toBeInTheDocument();

    // Scoped to the table — "Draft"/"Scheduled" also appear as <option>
    // text in the status filter <select>.
    const table = within(screen.getByRole("table"));
    expect(table.getByText("Draft")).toBeInTheDocument();
    expect(table.getByText("Scheduled")).toBeInTheDocument();
    expect(table.getByText("@ioncomms")).toBeInTheDocument();
  });

  it("filters by the selected status", async () => {
    const user = userEvent.setup();
    server.use(postsHandler([DRAFT_POST, SCHEDULED_POST]), accountsHandler([ACCOUNT_A1]));

    render(<TableRoute />);
    await screen.findByText("alpha post");

    await user.selectOptions(screen.getByLabelText("Status"), "scheduled");

    await waitFor(() => expect(screen.queryByText("alpha post")).not.toBeInTheDocument());
    expect(screen.getByText("beta post")).toBeInTheDocument();
  });

  it("sorts rows by Content when the column header is clicked", async () => {
    const user = userEvent.setup();
    // API returns "beta" before "alpha" — unsorted order is API order.
    server.use(postsHandler([SCHEDULED_POST, DRAFT_POST]), accountsHandler([ACCOUNT_A1]));

    render(<TableRoute />);
    await screen.findByText("alpha post");

    const beforeSort = screen.getAllByText(/^(alpha|beta) post$/).map((el) => el.textContent);
    expect(beforeSort).toEqual(["beta post", "alpha post"]);

    await user.click(screen.getByRole("button", { name: "Content" }));

    const afterAscending = screen
      .getAllByText(/^(alpha|beta) post$/)
      .map((el) => el.textContent);
    expect(afterAscending).toEqual(["alpha post", "beta post"]);
    expect(screen.getByRole("columnheader", { name: "Content" })).toHaveAttribute(
      "aria-sort",
      "ascending",
    );

    await user.click(screen.getByRole("button", { name: "Content" }));

    const afterDescending = screen
      .getAllByText(/^(alpha|beta) post$/)
      .map((el) => el.textContent);
    expect(afterDescending).toEqual(["beta post", "alpha post"]);
    expect(screen.getByRole("columnheader", { name: "Content" })).toHaveAttribute(
      "aria-sort",
      "descending",
    );
  });

  it("sorts rows by Status when the column header is clicked", async () => {
    const user = userEvent.setup();
    server.use(postsHandler([SCHEDULED_POST, DRAFT_POST]), accountsHandler([ACCOUNT_A1]));

    render(<TableRoute />);
    await screen.findByText("alpha post");

    await user.click(screen.getByRole("button", { name: "Status" }));

    // "draft" < "scheduled" lexicographically -> ascending puts the draft
    // (alpha post) first.
    const afterAscending = screen
      .getAllByText(/^(alpha|beta) post$/)
      .map((el) => el.textContent);
    expect(afterAscending).toEqual(["alpha post", "beta post"]);
    expect(screen.getByRole("columnheader", { name: "Status" })).toHaveAttribute(
      "aria-sort",
      "ascending",
    );
  });

  it("sorts rows by Scheduled for, always pushing unscheduled drafts last", async () => {
    const user = userEvent.setup();
    const draftA: PostDTO = { ...DRAFT_POST, id: "p-a", content: "delta post" };
    const draftB: PostDTO = { ...DRAFT_POST, id: "p-b", content: "epsilon post" };
    const earlyScheduled: PostDTO = {
      ...SCHEDULED_POST,
      id: "p-early",
      content: "alpha post",
      scheduled_at: "2099-01-01T00:00:00Z",
    };
    const lateScheduled: PostDTO = {
      ...SCHEDULED_POST,
      id: "p-late",
      content: "beta post",
      scheduled_at: "2099-06-01T00:00:00Z",
    };
    // Shuffled API order to prove sorting actually reorders.
    server.use(
      postsHandler([draftA, lateScheduled, draftB, earlyScheduled]),
      accountsHandler([ACCOUNT_A1]),
    );

    render(<TableRoute />);
    await screen.findByText("alpha post");

    const contentMatcher = /^(alpha|beta|delta|epsilon) post$/;

    await user.click(screen.getByRole("button", { name: "Scheduled for" }));
    expect(screen.getAllByText(contentMatcher).map((el) => el.textContent)).toEqual([
      "alpha post",
      "beta post",
      "delta post",
      "epsilon post",
    ]);

    await user.click(screen.getByRole("button", { name: "Scheduled for" }));
    // Descending flips the two SCHEDULED posts, but the unscheduled drafts
    // still sort last (in their original relative order) regardless of
    // direction — a draft has no meaningful chronological position.
    expect(screen.getAllByText(contentMatcher).map((el) => el.textContent)).toEqual([
      "beta post",
      "alpha post",
      "delta post",
      "epsilon post",
    ]);
  });

  it("refetches the list after a successful schedule from the row action", async () => {
    const user = userEvent.setup({ delay: null });
    const publishableDraft: PostDTO = { ...DRAFT_POST, account_ids: ["a-1"] };
    let posts: readonly PostDTO[] = [publishableDraft];

    server.use(
      http.get("/api/v1/queue/posts", () =>
        HttpResponse.json({ data: { posts, next_page_token: "" } }),
      ),
      http.post("/api/v1/queue/posts/p-1:schedule", async () => {
        const scheduled: PostDTO = {
          ...publishableDraft,
          status: "scheduled",
          scheduled_at: "2099-06-01T00:00:00Z",
        };
        posts = [scheduled];
        return HttpResponse.json({ data: scheduled });
      }),
      accountsHandler([ACCOUNT_A1]),
    );

    render(<TableRoute />);
    await screen.findByText("alpha post");

    await user.click(screen.getByRole("button", { name: "Schedule" }));
    const target = new Date(Date.now() + 2 * 24 * 60 * 60 * 1000);
    const pad = (n: number) => String(n).padStart(2, "0");
    const localValue = `${target.getFullYear()}-${pad(target.getMonth() + 1)}-${pad(target.getDate())}T${pad(target.getHours())}:${pad(target.getMinutes())}`;
    fireEvent.change(screen.getByLabelText("Date and time"), {
      target: { value: localValue },
    });

    await user.click(screen.getAllByRole("button", { name: "Schedule" })[1]);

    // Scoped to the table — "Scheduled" also appears as <option> text in
    // the status filter <select>.
    await waitFor(() =>
      expect(within(screen.getByRole("table")).getByText("Scheduled")).toBeInTheDocument(),
    );
    expect(screen.getByRole("button", { name: "Reschedule" })).toBeInTheDocument();
  });
});



